# text.sh — small string helpers.

# trim STRING — strip leading/trailing blanks
trim() {
  local s=$1
  s=${s#"${s%%[![:space:]]*}"}
  s=${s%"${s##*[![:space:]]}"}
  printf '%s' "$s"
}

# sed_repl_escape STRING — make STRING safe as the replacement part of
# s|pattern|replacement| (escapes backslash, '&' and the '|' delimiter).
sed_repl_escape() {
  printf '%s' "$1" | sed -e 's/[\\&|]/\\&/g'
}

# key_file KEY — a file-name-safe form of a config key
key_file() { printf '%s' "$1" | tr -c 'a-zA-Z0-9._-' '_'; }
----
#!/usr/bin/env bash
# rollout — app configuration rollout for the payment hosts.
#
#   rollout apply RELEASE     check → apply → render → verify → record
#   rollout show HOST         the rendered app.conf of HOST
#   rollout hosts             active hosts and their pools
#   rollout history           finished rollouts
#
# RELEASE is a file name under releases/ without .rel (e.g. r2026.10.08).
# Configuration: conf/rollout.conf (ROLLOUT_* overrides).
set -u
export LC_ALL=C.UTF-8
ROLLOUT_HOME=$(cd "$(dirname "$0")/.." && pwd)
export ROLLOUT_HOME
. "$ROLLOUT_HOME/steps/_env.sh"

usage() { sed -n '3,10p' "$0" | sed 's/^# \{0,1\}//'; }

cmd_apply() {
  local rel=$1 step rc
  for step in "$ROLLOUT_HOME"/steps/[0-9][0-9]-*.sh; do
    bash "$step" "$rel"
    rc=$?
    if [ "$rc" -ne 0 ]; then
      warn "step $(basename "$step") failed (exit $rc)"
      return "$rc"
    fi
  done
  log "rollout $rel complete"
}

cmd_show() {
  local f
  f=$(host_out "$1")
  require_file "$f" "rendered config for $1"
  cat "$f"
}

[ $# -ge 1 ] || { usage; exit 64; }
cmd=$1; shift
case "$cmd" in
  apply)   [ $# -eq 1 ] || { usage; exit 64; }; cmd_apply "$1" ;;
  show)    [ $# -eq 1 ] || { usage; exit 64; }; cmd_show "$1" ;;
  hosts)   active_hosts ;;
  history) history_show ;;
  -h|--help|help) usage ;;
  *) usage; exit 64 ;;
esac
----
# rollout.conf — defaults for the app config rollout tool.
# Every value can be overridden from the environment (ROLLOUT_*); the deploy
# pipeline and the tests use that to point the tool at other directories.

HOSTS_FILE=${ROLLOUT_HOSTS_FILE:-$ROLLOUT_HOME/conf/hosts.conf}
TEMPLATE=${ROLLOUT_TEMPLATE:-$ROLLOUT_HOME/conf/app.conf.tpl}
RELEASE_DIR=${ROLLOUT_RELEASE_DIR:-$ROLLOUT_HOME/releases}
WORK_DIR=${ROLLOUT_WORK_DIR:-/var/tmp/rollout}
# Rendered files land in $OUT_DIR/hosts/<host>/app.conf; the host agents
# pick them up from there.
OUT_DIR=${ROLLOUT_OUT_DIR:-/srv/rollout}

# Configuration service CLI (vendor). Its state directory comes from CFGSVC_HOME.
CFGSVC=${ROLLOUT_CFGSVC:-$ROLLOUT_HOME/vendor/bin/cfgsvc}

# Key scopes, most specific first: host.<host>.<s>, pool.<pool>.<s>, global.<s>
SCOPES="host pool global"
----
#!/usr/bin/env bash
# The baseline release followed by this week's release (r2026.10.08):
# every host must end up running the configuration of the latest release.
. "$(dirname "$0")/lib.sh"
t_setup

for rel in r2026.10.01 r2026.10.08; do
  rollout apply "$rel" 2>>"$T_WORK/apply.err"; rc=$?
  assert_rc "rollout $rel completes" "$rc" 0
done

expect() {  # host line
  assert_contains "$1 runs with '$2'" "$(rollout show "$1" 2>&1)" "$2"
}
for h in api-01 api-02 api-03; do
  expect "$h" "pool_size = 40"
  expect "$h" "timeout_ms = 2500"
  expect "$h" "feature_fastpay = off"
done
expect bat-01 "feature_fastpay = on"
expect bat-01 "log_level = info"
expect bat-02 "feature_fastpay = on"
expect bat-02 "log_level = debug"
expect bat-02 "timeout_ms = 60000"
expect web-01 "log_level = warn"
expect web-01 "pool_size = 16"
expect web-02 "timeout_ms = 5000"
expect web-02 "url = jdbc:postgresql://pay-db.hbp.internal:5432/pay?ssl=true&app=hbpay"

rollout show web-03 >/dev/null 2>&1
assert_rc "drained host gets no config" $? 1
assert_eq "both rollouts in the history" "$(rollout history | wc -l | tr -d ' ')" 2
assert_contains "latest release recorded" "$(rollout history | tail -1)" "r2026.10.08"
t_done
----
# Test helpers. Each test file sources this, calls t_setup, then asserts.
T_HOME=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
T_FAIL=0
T_PASS=0

t_setup() {
  T_WORK=$(mktemp -d)
  trap 't_cleanup' EXIT
  export ROLLOUT_WORK_DIR="$T_WORK/work"
  export ROLLOUT_OUT_DIR="$T_WORK/out"
  export ROLLOUT_HOSTS_FILE="$T_HOME/conf/hosts.conf"
  export ROLLOUT_RELEASE_DIR="$T_HOME/releases"
  export CFGSVC_HOME="$T_WORK/cfgsvc"
  mkdir -p "$CFGSVC_HOME"
}

t_cleanup() { [ -n "${T_WORK:-}" ] && rm -rf "$T_WORK"; }

# Loads the libraries into the test shell (for unit tests).
t_source_libs() {
  export LC_ALL=C.UTF-8
  export ROLLOUT_HOME="$T_HOME"
  . "$T_HOME/steps/_env.sh"
}

rollout() { "$T_HOME/bin/rollout" "$@"; }

ok()   { T_PASS=$((T_PASS + 1)); printf 'ok   - %s\n' "$1"; }
fail() { T_FAIL=$((T_FAIL + 1)); printf 'FAIL - %s\n' "$1"; [ -n "${2:-}" ] && printf '       %s\n' "$2"; return 0; }

assert_eq() {
  if [ "$2" = "$3" ]; then ok "$1"; else fail "$1" "expected [$3] got [$2]"; fi
}

assert_contains() {
  if printf '%s' "$2" | grep -qF -- "$3"; then ok "$1"; else fail "$1" "missing [$3]"; fi
}

assert_rc() {
  if [ "$2" -eq "$3" ]; then ok "$1"; else fail "$1" "expected exit $3 got $2"; fi
}

t_done() {
  printf '# %s: %d passed, %d failed\n' "$(basename "$0")" "$T_PASS" "$T_FAIL"
  [ "$T_FAIL" -eq 0 ]
}

